152	  const h = Math.floor(s / 3600);
153	  const m = Math.floor((s % 3600) / 60);
154	  const sec = s % 60;
155	  if (h) return `${h}h${String(m).padStart(2, '0')}m`;
156	  if (m) return `${m}m${String(sec).padStart(2, '0')}s`;
