170	  L: ['█    ', '█    ', '█    ', '█    ', '█████'],
171	  U: ['█   █', '█   █', '█   █', '█   █', ' ███ '],
172	  N: ['█   █', '██  █', '█ █ █', '█  ██', '█   █'],
173	  A: [' ███ ', '█   █', '█████', '█   █', '█   █'],
174	  C: [' ████', '█    ', '█    ', '█    ', ' ████'],
175	  O: [' ███ ', '█   █', '█   █', '█   █', ' ███ '],
176	  R: ['████ ', '█   █', '████ ', '█  █ ', '█   █'],
177	  E: ['█████', '█    ', '████ ', '█    ', '█████'],
178	};
179	function wordRows(word) {
180	  const rows = ['', '', '', '', ''];
181	  for (const ch of word) {
182	    const g = GLYPHS[ch];
183	    for (let r = 0; r < 5; r++) rows[r] += g[r] + ' ';
184	  }
