244	  // gutter = push the wordmark to the terminal's right edge; fall back to
245	  // "widest left line + 3" if the terminal is too narrow for that to fit
246	  const LEFTW = Math.max(
247	    Math.max(...left.map((s) => stripAnsi(s).length)) + 3,
248	    cols - artW
249	  );
250	  const out = art.map((a, i) => padTo(left[i] || '', LEFTW) + a);
251	  process.stdout.write(out.join('\n'));
252	}
253	
254	main();
